/* Only the documented C ABI leaves this object.
 *
 * Rust, V8, Skia and ICU symbols are implementation detail. Exporting them
 * would let a host bind to one by accident, which turns an internal change into
 * an ABI break -- and with V8 and Skia both inside, the accidental surface would
 * be tens of thousands of symbols wide.
 */
MIGO_1.0 {
    global:
        migo_*;
    local:
        *;
};
